BEGIN;
SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='1s';
DO $review$
DECLARE r record; f public.chatbot_knowledge_faq%ROWTYPE;
BEGIN
 FOR r IN SELECT * FROM (VALUES
(E'c0790b68-4583-4542-a788-95e4f284de6b'::uuid,E'Tôi có được đặt lịch mà chưa có tài khoản không?',E'Khách có thể tìm hiểu dịch vụ nhưng để thực hiện đặt lịch, PawPal yêu cầu đăng nhập hoặc hoàn tất quy trình tạo tài khoản theo chính sách hệ thống.\n(Quy định: Đặt lịch yêu cầu tài khoản hợp lệ.)',true,E'Có luồng đặt lịch dành cho khách vãng lai mà không bắt buộc tạo tài khoản thành viên. Bạn cung cấp thông tin liên hệ và hồ sơ bé, chọn dịch vụ, thời gian, xem lại báo giá rồi gửi yêu cầu. Giữ phiên khách hoặc thông tin khôi phục để xem lại biên nhận. Đã tiếp nhận yêu cầu chưa có nghĩa là đã thanh toán hoặc cửa hàng đã duyệt.',true,false),
(E'3fb93c32-890a-4c8c-9725-e05f00bd55a1'::uuid,E'Tôi có thể đặt lịch cho nhiều bé không?',E'PawPal hỗ trợ quản lý nhiều hồ sơ thú cưng. Bạn có thể đặt lịch cho từng bé theo quy tắc hệ thống.\n(Quy định: Mỗi lịch chỉ gắn với một bé và một dịch vụ.)',true,E'Mỗi yêu cầu đặt lịch hiện chọn một bé. Nếu có nhiều bé, bạn thực hiện yêu cầu riêng cho từng bé. Một lịch có gói chính và có thể có phần thêm được hệ thống cho phép; không có nghĩa mọi dịch vụ đều ghép chung được. Hãy kiểm tra báo giá và lịch khả dụng cho từng yêu cầu.',true,false),
(E'd5207e47-fcbd-4370-a7df-e39f6347b1f1'::uuid,E'Tôi có thể sử dụng nhiều dịch vụ cho bé cùng lúc không?',E'Mỗi lịch hẹn chỉ gắn với một dịch vụ. Nếu muốn sử dụng nhiều dịch vụ, bạn cần tạo các lịch tương ứng theo quy tắc hệ thống.\n(Quy định: Một lịch hẹn chỉ có một dịch vụ.)',true,E'Luồng đặt lịch cho phép chọn một gói chính và các phần thêm được cấu hình cho gói đó. Bạn xem những lựa chọn được hiển thị, thời lượng và báo giá trước khi gửi. Không phải mọi dịch vụ độc lập đều có thể ghép vào cùng một lịch; nếu chưa có lựa chọn phù hợp, hãy nhờ nhân viên kiểm tra.',true,false),
(E'bfd5e13e-b326-4fdd-ba99-4887472bd610'::uuid,E'Tôi không nhận được OTP thì sao?',E'Bạn kiểm tra số điện thoại và yêu cầu gửi lại OTP. Nếu vẫn không nhận được, hãy thực hiện lại theo hướng dẫn hoặc liên hệ hỗ trợ.\n(Quy định: OTP được gửi thông qua SMS Gateway.)',true,E'Kiểm tra lại số điện thoại và thông báo trên màn hình, chờ đến khi hệ thống cho phép gửi lại rồi thử theo hướng dẫn. Khả năng gửi và kênh nhận mã phụ thuộc cấu hình xác thực đang vận hành; FAQ này không xác nhận SMS đã được gửi thành công. Nếu vẫn không nhận được, hãy liên hệ nhân viên. Không gửi mã OTP hoặc mật khẩu vào chat.',true,false),
(E'ff17d777-6a4a-4faa-ad8d-14eee3bb8b13'::uuid,E'Tôi có bắt buộc phải có tài khoản mới được mua hàng không?',E'Khách có thể tìm hiểu dịch vụ và sản phẩm mà không cần tài khoản. Khi thực hiện giao dịch, hệ thống có thể tạo tài khoản tạm thời theo quy trình phù hợp.\n(Quy định: Tài khoản tạm thời được xử lý theo quy trình hệ thống.)',true,E'Bạn có thể mua bằng luồng khách vãng lai mà không phải tạo tài khoản thành viên. Chọn sản phẩm và biến thể, nhập thông tin liên hệ, chọn nhận tại cửa hàng hoặc hình thức giao nhận được hỗ trợ, kiểm tra tổng tiền rồi đặt hàng. Giữ phiên khách hoặc mã khôi phục để tra cứu. Tạo đơn thành công không đồng nghĩa đã thanh toán; hệ thống không tự ghép hồ sơ thành viên chỉ vì trùng số điện thoại.',true,false),
(E'b21eb012-acf9-41d9-94b6-91943e144bff'::uuid,E'PawPal có mở cửa cuối tuần hoặc ngày lễ không?',E'Thời gian hoạt động phụ thuộc lịch làm việc của từng chi nhánh. Mình có thể kiểm tra lịch hoạt động và khả năng tiếp nhận theo ngày bạn dự kiến.\n(Quy định: Tra cứu lịch hoạt động thực tế.)',true,E'FAQ hiện chưa có lịch mở cửa đã xác nhận cho từng ngày cuối tuần, ngày lễ hoặc chi nhánh. Bạn kiểm tra thông tin liên hệ và các khung giờ được hiển thị tại bước đặt lịch, hoặc nhờ nhân viên xác nhận ngày dự kiến. Chat tư vấn này chưa xác nhận cửa hàng mở cửa hoặc còn chỗ cho ngày bạn hỏi.',true,false),
(E'c8b9a460-f5f4-4c0d-8ac7-a4bde1331cb0'::uuid,E'PawPal có những chi nhánh nào?',E'Bạn có thể xem các chi nhánh đang hoạt động và lựa chọn chi nhánh phù hợp với dịch vụ.\n(Quy định: Danh sách chi nhánh và dịch vụ phải được tra cứu từ dữ liệu hiện hành.)',true,E'FAQ hiện chưa liệt kê tên và địa chỉ chi nhánh đã được xác nhận. Bạn vui lòng xem thông tin liên hệ công khai của PawPal hoặc gặp nhân viên để xác nhận địa điểm phù hợp; chat không tự tạo địa chỉ hay suy đoán chi nhánh đang phục vụ.',true,false),
(E'207a3d0a-72bf-4678-888d-e50ae4ce00d5'::uuid,E'Nếu khung giờ tôi muốn đã kín thì sao?',E'Mình có thể kiểm tra các khung giờ còn khả dụng và gợi ý lựa chọn khác nếu hệ thống có dữ liệu phù hợp.\n(Quy định: Không tự tạo hoặc giữ chỗ khi chưa có xác nhận.)',true,E'Bạn có thể xem và chọn khung giờ khác được hệ thống hiển thị tại bước đặt lịch hoặc nhờ nhân viên hỗ trợ. Chat tư vấn này chưa kiểm tra hoặc giữ chỗ thay bạn; khung giờ và giá cần được kiểm tra lại khi gửi yêu cầu.',true,false),
(E'c315a5d0-4709-49a2-8791-13a5da72f4b6'::uuid,E'PawPal có khuyến mãi dịch vụ không?',E'PawPal có thể triển khai chương trình ưu đãi theo từng thời điểm. Mình có thể kiểm tra các chương trình đang hoạt động và điều kiện áp dụng.\n(Quy định: Chỉ giới thiệu khuyến mãi còn hiệu lực.)',true,E'Ưu đãi có thể thay đổi theo thời điểm và điều kiện áp dụng. FAQ này chưa cung cấp danh sách chương trình còn hiệu lực hoặc xác nhận bạn đủ điều kiện. Hãy kiểm tra ưu đãi được hiển thị và kết quả áp dụng tại bước xem giá, hoặc nhờ nhân viên xác nhận; không mặc định được giảm giá.',true,false),
(E'112d121d-2dde-4694-8352-950e9a0455f4'::uuid,E'QA kiểm thử lưu FAQ 2026-10-15',E'Đã cập nhật nội dung trả lời FAQ kiểm thử 2026-10-15.',true,E'Đã cập nhật nội dung trả lời FAQ kiểm thử 2026-10-15.',false,false),
(E'15700000-0000-4000-8000-000000000011'::uuid,E'Khách vãng lai mua hàng như thế nào?',NULL::text,NULL::boolean,E'Chọn sản phẩm và biến thể, thêm vào giỏ hoặc vào bước mua, nhập thông tin liên hệ và giao nhận cần thiết, chọn phương thức thanh toán được hiển thị rồi kiểm tra đơn hàng. Chỉ bấm đặt khi đã xem kết quả kiểm tra. Sau khi tạo, giữ biên nhận và thông tin khôi phục; trạng thái đơn và thanh toán được hiển thị riêng.',true,true),
(E'15700000-0000-4000-8000-000000000012'::uuid,E'Phí giao hàng và phạm vi giao nhận được xác nhận ở đâu?',NULL::text,NULL::boolean,E'Chọn hình thức giao nhận và cung cấp địa chỉ cần thiết tại bước mua hàng, sau đó dùng chức năng kiểm tra đơn để xem phí và tổng tiền hiện được áp dụng. Không mặc định miễn phí hoặc giao được mọi địa chỉ. Nếu hệ thống không đưa ra lựa chọn phù hợp, hãy nhờ nhân viên kiểm tra.',true,true),
(E'15700000-0000-4000-8000-000000000013'::uuid,E'Tôi muốn đổi trả hàng thì làm thế nào?',NULL::text,NULL::boolean,E'Bạn sử dụng mục đổi trả trong tài khoản hoặc luồng tra cứu dành cho khách vãng lai khi đã xác minh được quyền với giao dịch, hoặc nhờ nhân viên hỗ trợ. Chuẩn bị thông tin đơn và lý do cần đổi trả. FAQ này chưa xác nhận thời hạn, phí, điều kiện được chấp thuận hoặc khoản hoàn cho trường hợp của bạn; gửi yêu cầu không đồng nghĩa đã được duyệt.',true,true),
(E'0cbebd64-3ab1-456d-b3df-e78166ce78c2'::uuid,E'PawPal phục vụ những loài thú cưng nào?',E'Phạm vi tiếp nhận phụ thuộc vào từng dịch vụ và danh mục thú cưng được hỗ trợ. Bạn cho mình biết loài thú cưng và dịch vụ mong muốn để mình kiểm tra chính xác nhé.\n(Quy định: Không tự khẳng định nhận loài chưa được xác nhận trong danh mục.)',true,E'Phạm vi tiếp nhận phụ thuộc từng gói dịch vụ và loài được gói đó hỗ trợ. Bạn kiểm tra thông tin gói và các lựa chọn được hiển thị khi đặt cho bé, hoặc nhờ nhân viên xác nhận. FAQ này chưa có danh sách loài đã xác nhận cho từng gói; chat không tự khẳng định mọi loài đều được nhận.',true,false),
(E'44e613e9-3f08-4365-b1c1-e2a96f5646ea'::uuid,E'Có thể gửi bé nhiều ngày hoặc qua đêm không?',E'PawPal hỗ trợ lưu trú theo thời gian và loại phòng đang được cung cấp. Bạn có thể cho biết ngày gửi và ngày đón để mình kiểm tra.\n(Quy định: Kiểm tra tình trạng phòng và thời gian lưu trú.)',true,E'Bạn có thể xem lựa chọn thời gian lưu trú và loại phòng ở bước đặt Pet Hotel, hoặc nhờ nhân viên xác nhận nhu cầu gửi và đón bé. FAQ này chưa xác nhận phòng trống, thời gian tiếp nhận hay báo giá cho khoảng lưu trú cụ thể; cần kiểm tra trước khi gửi yêu cầu.',true,false),
(E'4c7d461d-1901-4a1b-80c3-e178f5e6a152'::uuid,E'Gửi Hotel ngày lễ, Tết có phụ thu không?',E'Mức giá ngày lễ, Tết phụ thuộc chính sách giá và phụ thu đang áp dụng. Bạn cho mình biết ngày gửi và ngày đón để mình kiểm tra.\n(Quy định: Không tự đặt ra mức phụ thu.)',true,E'FAQ này chưa có mức phụ thu hoặc điều kiện đã xác nhận cho ngày lễ, Tết. Bạn xem báo giá ở bước đặt và nhờ nhân viên xác nhận ngày gửi, ngày đón cùng phụ phí nếu có. Không tự cộng phần trăm phụ thu hoặc coi giá ngày thường là giá cuối cùng cho ngày lễ.',true,false),
(E'b44caf50-c88f-4506-8629-b7258ce367cc'::uuid,E'Dịch vụ mất bao lâu?',E'Thời lượng dự kiến phụ thuộc vào gói dịch vụ và đặc điểm thực tế của bé. Mình có thể tra cứu thời lượng được cấu hình cho dịch vụ bạn quan tâm.\n(Quy định: Không tự cam kết thời gian hoàn thành nếu chưa có dữ liệu.)',true,E'Bạn xem thời lượng dự kiến được hiển thị ở gói dịch vụ và bước đặt lịch. Phần thêm và tình trạng thực tế của bé có thể làm nhu cầu xử lý khác nhau; nếu cần thời gian nhận/trả cụ thể hãy nhờ nhân viên xác nhận. Thời lượng dự kiến chưa phải cam kết giờ hoàn tất, và FAQ này chưa xác nhận thời lượng của một gói chưa được chọn.',true,false),
(E'679d2966-9482-4e4a-8013-154185dd676b'::uuid,E'Tôi xem trạng thái đơn hàng ở đâu?',E'Bạn có thể tra cứu trạng thái đơn hàng theo mã đơn. Thành viên có thể xem thêm trong mục Đơn hàng của tôi.\n(Quy định: Chỉ cung cấp trạng thái được hệ thống ghi nhận.)',true,E'Thành viên xem đơn trong tài khoản của mình. Khách vãng lai sử dụng phiên khách hoặc cơ chế khôi phục và xác minh tại mục tra cứu, hoặc nhờ nhân viên hỗ trợ. Chỉ biết mã đơn hay số điện thoại không tự tạo quyền xem đơn; chat tư vấn công khai này chưa xác minh hoặc tra trạng thái giao dịch thay bạn.',true,false),
(E'63ae90ff-0d7e-4147-8ce1-9de26ce08023'::uuid,E'Tôi có bao nhiêu Paw Points?',E'Bạn có thể kiểm tra số dư Paw Points trong tài khoản. Nếu cần tra cứu dữ liệu cá nhân, Chatbot sẽ yêu cầu xác thực phù hợp.\n(Quy định: Không cung cấp thông tin điểm của tài khoản khác.)',true,E'Bạn kiểm tra điểm trong tài khoản đã đăng nhập của mình hoặc nhờ nhân viên hỗ trợ theo quy trình xác minh. Chat tư vấn công khai này chưa xác minh hoặc tra số dư điểm cho bạn; không cung cấp dữ liệu điểm của người khác và không tự suy số dư từ nội dung hội thoại.',true,false)) x(id,question,old_answer,old_active,new_answer,new_active,is_new) LOOP
  SELECT * INTO f FROM public.chatbot_knowledge_faq WHERE id=r.id FOR UPDATE;
  IF NOT FOUND AND r.is_new THEN CONTINUE; END IF;
  IF NOT FOUND THEN RAISE EXCEPTION 'public_faq_missing_review_required' USING ERRCODE='22023'; END IF;
  IF NOT r.is_new AND f.question=r.question AND f.answer=r.old_answer AND f.is_active=r.old_active THEN CONTINUE; END IF;
  IF f.question<>r.question OR f.answer IS DISTINCT FROM r.new_answer OR f.is_active IS DISTINCT FROM r.new_active THEN RAISE EXCEPTION 'public_faq_changed_review_required' USING ERRCODE='22023'; END IF;
  IF r.is_new AND (f.category<>'H??ng d?n c?ng khai' OR f.keywords<>'{}'::text[] OR f.priority<>20) THEN RAISE EXCEPTION 'public_faq_metadata_changed_review_required' USING ERRCODE='22023'; END IF;
  IF r.is_new THEN DELETE FROM public.chatbot_knowledge_faq WHERE id=r.id;
  ELSE UPDATE public.chatbot_knowledge_faq SET answer=r.old_answer,is_active=r.old_active,updated_at=clock_timestamp() WHERE id=r.id; END IF;
 END LOOP;
END $review$;
COMMIT;
